def count_reachable_squares(R, C, K):
    def is_reachable(r, c, R, C):
        return abs(r - R) <= 1 and abs(c - C) <= 1

    count = 0
    for r in range(1, 9):
        for c in range(1, 8):
            if is_reachable(r, c, R, C) and (abs(r - R) + abs(c - C)) <= K:
                count += 1
    return count

